script:
# Inspect the differential analysis xlsx
xlsx_path <- "inputs/differential-results-333333333333.xlsx"
# Try to list sheet names without reading the whole file
sheets <- tryCatch({
  # Try a few methods
  if (requireNamespace("readxl", quietly = TRUE)) {
    readxl::excel_sheets(xlsx_path)
  } else if (requireNamespace("openxlsx", quietly = TRUE)) {
    openxlsx::getSheetNames(xlsx_path)
  } else {
    "no_xlsx_reader"
  }
}, error = function(e) paste("error:", e$message))
cat("Sheets:", paste(sheets, collapse = ", "), "\n")
# Check available packages
cat("\nAvailable packages for xlsx:\n")
for (pkg in c("readxl", "openxlsx", "xlsx", "XLConnect")) {
  cat(pkg, ":", requireNamespace(pkg, quietly = TRUE), "\n")
}
